mapper.update:
UPDATE t_group_xiaohao_day_history
SET profit = profit + ${agentIncome},dayingjia_count = dayingjia_count + ${dayingjiaCount}
where group_id = #{groupId} and hehuoren_id = #{hehuorenId} and DATE_FORMAT(day_time,'%Y-%m-%d') = #{now_data}

mapper.select:
SELECT ifnull(sum(profit),0) as xiaohaoCount ,ifnull(sum(dayingjia_count),0) as dayingjiaCount ,ifnull(sum(player_count),0) as playerCount  from t_group_xiaohao_day_history
where group_id = ${groupId} and hehuoren_id = ${playerId}

  and DATE_FORMAT(day_time,'%Y-%m-%d') >= #{startTime}


  and DATE_FORMAT(day_time,'%Y-%m-%d') <= #{endTime}
